import { readFile, writeFile as writeRaw } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { format, resolveConfig } from 'prettier';

/** Generated files are written the way the formatter of the package would leave them. */
const writeFile = async (url, code) => {
  const options = await resolveConfig(fileURLToPath(url));
  await writeRaw(url, await format(code, { ...options, parser: 'typescript' }));
};
const root = new URL('../', import.meta.url);
const data = JSON.parse(
  await readFile(new URL('node_modules/@iconify-json/lucide/icons.json', root), 'utf8'),
);
const manifest = JSON.parse(
  await readFile(new URL('node_modules/@iconify-json/lucide/package.json', root), 'utf8'),
);
const names = [
  'square-pen',
  'grip-vertical',
  'arrow-up',
  'arrow-down',
  'copy',
  'trash-2',
  'corner-left-up',
  'image',
  'code-xml',
  'plus',
  'app-window',
];
const icons = Object.fromEntries(
  names.map((name) => {
    const body = data.icons[name]?.body;
    if (!body) throw new Error('MISSING_CANVAS_ICON:' + name);
    return [name, body];
  }),
);
await writeFile(
  new URL('src/renderers/canvas-icons.ts', root),
  '// Generated by scripts/canvas-icons.mjs from @iconify-json/lucide@' +
    manifest.version +
    '. Do not draw or edit icon bodies here.\n' +
    'export const CANVAS_ICONS: Readonly<Record<string, string>> = Object.freeze(' +
    JSON.stringify(icons, null, 2) +
    ');\n',
);

const uiNames = [
  ...new Set([
    ...names,
    'bold',
    'italic',
    'underline',
    'strikethrough',
    'link',
    'check',
    'x',
    'type',
    'list',
    'list-ordered',
    'chevron-down',
    'chevron-up',
    'chevron-left',
    'chevron-right',
    'chevrons-up-down',
    'search',
    'loader-circle',
    'minus',
    'plus',
    'ellipsis',
    'remove-formatting',
    'arrow-down-to-line',
    'arrow-up-to-line',
    'box',
    'braces',
    'circle-question-mark',
    'clipboard-copy',
    'clipboard-paste',
    'columns-2',
    'download',
    'file',
    'file-json',
    'heading',
    'keyboard',
    'layout-grid',
    'layout-template',
    'list-tree',
    'monitor',
    'mouse-pointer-click',
    'palette',
    'moon',
    'bookmark-plus',
    'list-checks',
    'circle-alert',
    'circle-check',
    'panel-bottom',
    'panel-left',
    'panel-right',
    'pilcrow',
    'rectangle-vertical',
    'redo-2',
    'rotate-ccw',
    'rows-2',
    'save',
    'smartphone',
    'square',
    'square-dashed',
    'square-plus',
    'tablet',
    'text-cursor-input',
    'triangle-alert',
    'undo-2',
    'unfold-vertical',
    'unlink',
    'upload',
    'moon',
    'bookmark-plus',
    'sun',
    'info',
  ]),
];
const uiIcons = Object.fromEntries(
  uiNames.map((name) => {
    const body = data.icons[name]?.body;
    if (!body) throw new Error('MISSING_EDITOR_ICON:' + name);
    return [name, { body }];
  }),
);
await writeFile(
  new URL('src/vue/icon-data.ts', root),
  '// Generated from @iconify-json/lucide@' +
    manifest.version +
    ' by scripts/canvas-icons.mjs.\n' +
    'export const EDITOR_ICON_DATA = ' +
    JSON.stringify(uiIcons, null, 2) +
    ';\n',
);
